#!/bin/sh

# SPDX-License-Identifier: Apache-2.0
# Adapted from Cosmos SDK, scripts/protocgen.sh.
# Modified for Ark: schema selection, output paths, stale-output cleanup, and dual generation.
# See NOTICE and THIRD_PARTY_NOTICES.md for upstream attribution.

# Run from the repo root inside the proto-builder image the Makefile pins:
#   make proto-gen

set -eu

echo "Formatting protobuf files"
buf format -w proto

# Gogo output sits beside handwritten code, so clear only generated files an Ark schema owns: a
# deleted schema or service then leaves nothing behind. A github.com tree is an interrupted run's.
echo "Cleaning gogo output"
rm -rf github.com
find . \( -path ./.git -o -path ./api -o -path ./proto \) -prune -o \
  -type f \( -name '*.pb.go' -o -name '*.pb.gw.go' \) -print |
  while IFS= read -r generated; do
    case "$(head -n 1 "$generated")" in
      '// Code generated by '*'. DO NOT EDIT.') ;;
      *) continue ;;
    esac
    if sed -n '1,12p' "$generated" | grep -q '^// source: ark/'; then
      rm -f "$generated"
    fi
  done

echo "Generating gogo proto code"
cd proto
proto_dirs=$(find ./ark -name '*.proto' -print0 | xargs -0 -n1 dirname | sort | uniq)
for dir in $proto_dirs; do
  for file in $(find "${dir}" -maxdepth 1 -name '*.proto'); do
    # Schemas without a go_package, the module configs, are Pulsar only.
    if grep -q '^option go_package' "$file"; then
      buf generate --template buf.gen.gogo.yaml "$file"
    fi
  done
done

cd ..

# Move gocosmos output from the go_package module-path tree into repository-relative package
# directories.
if [ -d "github.com" ]; then
  cp -r github.com/ararat-network/ark/* ./
  rm -rf github.com
fi

./proto/scripts/protocgen-pulsar.sh
